from gurobipy import Model, GRB, quicksum

def build_and_solve_transportation_model():
    supply_records = [r for r in LEGACY_RECORDS if r['source'].endswith('supply_capacity.csv')]
    warehouse_ids = []
    supply_capacity = {}
    for r in supply_records:
        wid = r['values']['Unnamed: 0']
        warehouse_ids.append(wid)
        supply_capacity[wid] = float(r['values']['supply_capacity'])
    demand_records = [r for r in LEGACY_RECORDS if r['source'].endswith('customer_demand.csv')]
    customer_ids = []
    customer_demand = {}
    for r in demand_records:
        cid = r['values']['customer']
        customer_ids.append(cid)
        customer_demand[cid] = float(r['values']['demand'])
    cost_records = [r for r in LEGACY_RECORDS if r['source'].endswith('transportation_costs.csv')]
    transportation_cost = {}
    for r in cost_records:
        wid = r['values']['Unnamed: 0']
        transportation_cost[wid] = {}
        for cid in customer_ids:
            if cid not in r['values']:
                raise ValueError(f'Missing cost for warehouse {wid}, customer {cid}')
            transportation_cost[wid][cid] = float(r['values'][cid])
    for wid in warehouse_ids:
        if wid not in transportation_cost:
            raise ValueError(f'Missing cost row for warehouse {wid}')
        for cid in customer_ids:
            if cid not in transportation_cost[wid]:
                raise ValueError(f'Missing cost for warehouse {wid}, customer {cid}')
    m = Model()
    x_vars = m.addVars(warehouse_ids, customer_ids, lb=0.0, vtype=GRB.CONTINUOUS, name='')
    m.setObjective(quicksum((transportation_cost[w][c] * x_vars[w, c] for w in warehouse_ids for c in customer_ids)), GRB.MINIMIZE)
    for c in customer_ids:
        m.addConstr(quicksum((x_vars[w, c] for w in warehouse_ids)) == customer_demand[c], name=f'demand_{c}')
    for w in warehouse_ids:
        m.addConstr(quicksum((x_vars[w, c] for c in customer_ids)) <= supply_capacity[w], name=f'supply_{w}')
    m.Params.MIPGap = 0.0001
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(m.ObjVal)
        for w in warehouse_ids:
            for c in customer_ids:
                v = x_vars[w, c]
                print(f'{v.VarName} {v.X}')
    else:
        print(m.Status)
    return m
m = build_and_solve_transportation_model()